    GameRandom game(17);WatcomRandom random(91);CareerSnapshot state;state.world=bmh::test::world12::inactive_national_fixture(master,reference,primary,game,random);auto& record=*std::find_if(state.world.national_coaches->begin(),state.world.national_coaches->end(),[&](const auto& record){return record.startup.has_value();});const auto team=record.team;record.view_preferences=initial_national_view_preferences(reference,0);state.world.settings->duration=duration;state.world.managers.push_back({0,"National owner",team,{},0});state.world.annual_awards_completed=0;state.world.annual_title_archive.emplace();state.world.highscore_signature=0;activate_national_coaches(state.world,{0});for(auto country:{Country::germany,Country::england})nominate_national_squad(state.world,country,0,reference,random);
