    state.results=SeasonResults::empty(state.world.catalogue);state.game_seed=game.seed();state.watcom_seed=random.seed();initialize_career_economy(state,reference);state.desktop.emplace();state.desktop->manager_order={0};state.desktop->matchday_number=60;state.desktop->autosave_month=7;state.desktop->managers.push_back({0});state.date=365;state.calendar=CalendarCursor{SeasonCalendar{},365,365};const auto epoch=calendar_epoch();state.progress=CareerProgress{ProgressPhase::season_end,DayEntry::plain_day,364,0,uint16_t(epoch.year),uint8_t(epoch.weekday),0};state.validate();return state;
